function validarCorreo(e){let o=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);return console.log("validarCorreo:",e,":",o),o}function soloLetras(e){let o=/^[A-Za-zÁÉÍÓÚáéíóúÜüÑñ\s]+$/.test(e);return console.log("soloLetras:",e,":",o),o}function validarLongitud(e,o){let a=String(e).length<=o;return console.log("validarLongitud:",e,"máximo:",o,":",a),a}function calcularEdad(e){let o=new Date(e+"T00:00:00"),a=new Date,t=a.getFullYear()-o.getFullYear(),l=a.getMonth()-o.getMonth();return(l<0||0===l&&a.getDate()<o.getDate())&&t--,console.log("calcularEdad:",e,":",t),t}function esMayorDeEdad(e){let o=calcularEdad(e)>=18;return console.log("esMayorDeEdad:",e,":",o),o}function validarPassword(e){let o=/[A-Z]/.test(e),a=/[a-z]/.test(e),t=/[0-9]/.test(e),l=/[^A-Za-z0-9\s]/.test(e),r=e.length>=8,n=o&&a&&t&&l&&r;return console.log("validarPassword:",e,":",n),n}function esCorreoInstitucional(e){let o=e.trim().toLowerCase().match(/^[^\s@]+@([^\s@]+)$/);if(!o)return console.log("esCorreoInstitucional:",e,":",!1),!1;let a=o[1];return["gmail.com","yahoo.com","hotmail.com","outlook.com","icloud.com"].includes(a)?(console.log("esCorreoInstitucional:",e,":",!1),!1):(console.log("esCorreoInstitucional:",e,":",!0),!0)}function validarEstado(e){let o,a=String(e),t="";for(let e=0;e<=2;e++)t+=a.charAt(e);switch(t){case"951":o="oaxaca";break;case"998":o="Cancún";break;case"614":o="Chihuahua";break;case"220":case"221":case"222":o="Puebla";break;case"443":o="Morelia";break;case"442":case"446":o="Querétaro";break;default:o="Desconocido"}return console.log("validarEstado:",e,"LADA:",t,":",o),o}console.log("Hola desde la utilería");